var ETZ_CHAIM_PASSES=Object.freeze([{id:"blocking",label:"Blocking",discipline:"staging",priority:10},{id:"pose",label:"Pose & Silhouette",discipline:"body",priority:20},{id:"lipSync",label:"Lip Sync",discipline:"face",priority:30},{id:"eyeFocus",label:"Eye Focus",discipline:"face",priority:40},{id:"handContact",label:"Hand Contact",discipline:"interaction",priority:50},{id:"linePolish",label:"Line Polish",discipline:"finish",priority:60},{id:"furCloth",label:"Fur & Cloth",discipline:"secondary",priority:60},{id:"cameraPolish",label:"Camera Polish",discipline:"camera",priority:70}]),OlamAnimationPassCatalog=class{static details(sodBeatIndex=0){return["blocking","pose","lipSync","eyeFocus","handContact",sodBeatIndex%5===0?"furCloth":"linePolish","cameraPolish"].map(shemPass=>({...ETZ_CHAIM_PASSES.find(kli=>kli.id===shemPass)}))}static ids(sodBeatIndex=0){return this.details(sodBeatIndex).map(kli=>kli.id)}};var AnimationPassEngine=class{static build(sederPlan={}){let olamBeats=Array.isArray(sederPlan?.beats)?sederPlan.beats:[],keterFps=Number.isFinite(Number(sederPlan?.fps))&&Number(sederPlan.fps)>0?Number(sederPlan.fps):24;return olamBeats.map((kliBeat,sodIndex)=>this.buildBeat(kliBeat,sodIndex,keterFps))}static buildBeat(kliBeat={},sodIndex=0,keterFps=24){let gevurahDuration=Math.max(0,Number(kliBeat?.duration)||0),orDetails=OlamAnimationPassCatalog.details(sodIndex);return{beatId:kliBeat?.id,passes:orDetails.map(kli=>kli.id),estimatedFrames:Math.ceil(gevurahDuration/1e3*keterFps),status:"planned",fps:keterFps,durationMs:gevurahDuration,passDetails:orDetails}}};export{AnimationPassEngine};
